import re

DATE_RE = re.compile(r"\b\d{4}-\d{2}-\d{2}\b")

def find_dates(text):
    return DATE_RE.findall(text)

import re

SPACE_RE = re.compile(r" {2,}")

def collapse_spaces(text):
    return SPACE_RE.sub(" ", text)

function slugify(text) {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

import re

TAG_RE = re.compile(r"<[^>]+>")

def strip_tags(html):
    return TAG_RE.sub("", html)

function fileExtension(name) {
  const m = name.match(/\.([a-z0-9]+)$/i);
  return m ? m[1] : null;
}

import re

KV_RE = re.compile(r"(\w+)=(.*)")

def parse_kv(line):
    m = KV_RE.match(line)
    return {m.group(1): m.group(2)} if m else {}

function hashtags(tweet) {
  return (tweet.match(/#[a-zA-Z0-9_]+/g) || []).map((t) => t.slice(1));
}

function toSnakeCase(key) {
  return key.replace(/[A-Z]/g, (c) => `_${c.toLowerCase()}`);
}

import re

SPLIT_RE = re.compile(r",(?=(?:[^\"]*\"[^\"]*\")*[^\"]*$)")

def split_fields(line):
    return SPLIT_RE.split(line)

import re

COMMENT_RE = re.compile(r"/\*.*?\*/", re.DOTALL)

def strip_css_comments(css):
    return COMMENT_RE.sub("", css)

function toTitleCase(s) {
  return s.replace(/\b[a-z]/g, (c) => c.toUpperCase());
}

import re

NON_DIGIT_RE = re.compile(r"\D")

def digits_only(phone):
    return NON_DIGIT_RE.sub("", phone)
